// Every identifier in this app is generated by reading the current maximum and
// adding one. Two requests that arrive together read the same maximum and
// produce the same number. Where the target has a unique index the second write
// fails with E11000; where it does not, both writes succeed and the duplicate
// is stored.
//
// These helpers make both cases safe: retry on a duplicate-key error, and give
// callers a way to express "insert only if this value is not already there".

const isDuplicateKeyError = (error) =>
  Boolean(error) && (error.code === 11000 || error.code === 11001);

// Run fn, retrying when a unique index rejects the generated value. fn is
// expected to recompute the identifier on each attempt.
const withDuplicateRetry = async (fn, attempts = 5) => {
  let lastError;
  for (let attempt = 0; attempt < attempts; attempt++) {
    try {
      return await fn(attempt);
    } catch (error) {
      if (!isDuplicateKeyError(error)) throw error;
      lastError = error;
    }
  }
  throw lastError;
};

// Run fn until it returns something other than null, which callers use to
// signal "the conditional update matched nothing, so the value was taken".
const withConflictRetry = async (fn, attempts = 5) => {
  for (let attempt = 0; attempt < attempts; attempt++) {
    const result = await fn(attempt);
    if (result) return result;
  }
  return null;
};

module.exports = { isDuplicateKeyError, withDuplicateRetry, withConflictRetry };
